"""Execute compiler-generated bytes in an independent CPU implementation.

Unicorn is an optional, test-only dependency; no compiler runtime uses it.
Each call has a fresh address space, a finite instruction budget, and explicit
ABI entry/exit checks. Expectations are calculated here, not by Physical IR.
"""
import argparse
import math
import random
import struct
import subprocess
import sys

parser = argparse.ArgumentParser()
parser.add_argument('--compiler', required=True)
parser.add_argument('--python-path', required=True)
args = parser.parse_args()
sys.path.insert(0, args.python_path)
import unicorn as uc
from unicorn import x86_const as x86, arm64_const as arm, riscv_const as rv

MASK = (1 << 64) - 1
STOP = 0x1F0000
STACK = 0x400000
INITIAL_SP = STACK + 0x80000


def unsigned_f32(value):
    # Round the integer directly to binary32, avoiding a binary64 intermediate.
    shift = max(0, value.bit_length() - 24)
    significand = value >> shift
    if shift:
        remainder = value & ((1 << shift) - 1)
        half = 1 << (shift - 1)
        if remainder > half or (remainder == half and significand & 1): significand += 1
    return math.ldexp(significand, shift)


def execute(mode, functions, name, values, floating=False, argument_kinds=None, result_kind=None):
    argument_kinds = argument_kinds or [('f64' if floating else 'u64')] * len(values)
    result_kind = result_kind or ('f64' if floating else 'u64')
    if mode < 2:
        cpu = uc.Uc(uc.UC_ARCH_X86, uc.UC_MODE_64)
        gprs = [getattr(x86, 'UC_X86_REG_' + n) for n in
                (['RCX', 'RDX', 'R8', 'R9'] if mode else ['RDI', 'RSI', 'RDX', 'RCX', 'R8', 'R9'])]
        fprs = [getattr(x86, f'UC_X86_REG_XMM{i}') for i in range(4 if mode else 8)]
        saved = [getattr(x86, 'UC_X86_REG_' + n) for n in
                 (['RBX', 'RBP', 'R12', 'R13', 'R14', 'R15', 'RSI', 'RDI'] if mode else ['RBX', 'RBP', 'R12', 'R13', 'R14', 'R15'])]
        if mode: saved += [getattr(x86, f'UC_X86_REG_XMM{i}') for i in range(6, 16)]
        sp_reg, ret_reg, pc_reg = x86.UC_X86_REG_RSP, x86.UC_X86_REG_RAX, x86.UC_X86_REG_RIP
        sp = INITIAL_SP - 8
        stack_bias = 40 if mode else 8
    elif mode == 2:
        cpu = uc.Uc(uc.UC_ARCH_ARM64, uc.UC_MODE_ARM)
        cpu.reg_write(arm.UC_ARM64_REG_CPACR_EL1, 3 << 20)
        gprs = [getattr(arm, f'UC_ARM64_REG_X{i}') for i in range(8)]
        fprs = [getattr(arm, f'UC_ARM64_REG_D{i}') for i in range(8)]
        saved = [getattr(arm, f'UC_ARM64_REG_X{i}') for i in range(19, 30)]
        saved += [getattr(arm, f'UC_ARM64_REG_D{i}') for i in range(8, 16)]
        sp_reg, ret_reg, pc_reg = arm.UC_ARM64_REG_SP, arm.UC_ARM64_REG_X0, arm.UC_ARM64_REG_PC
        cpu.reg_write(arm.UC_ARM64_REG_X30, STOP)
        sp, stack_bias = INITIAL_SP, 0
    else:
        cpu = uc.Uc(uc.UC_ARCH_RISCV, uc.UC_MODE_RISCV64)
        cpu.reg_write(rv.UC_RISCV_REG_MSTATUS, 3 << 13)
        gprs = [getattr(rv, f'UC_RISCV_REG_X{i}') for i in range(10, 18)]
        fprs = [getattr(rv, f'UC_RISCV_REG_F{i}') for i in range(10, 18)]
        saved = [getattr(rv, f'UC_RISCV_REG_X{i}') for i in [8, 9, *range(18, 28)]]
        if mode == 5: saved += [getattr(rv, f'UC_RISCV_REG_F{i}') for i in [8, 9, *range(18, 28)]]
        sp_reg, ret_reg, pc_reg = rv.UC_RISCV_REG_X2, rv.UC_RISCV_REG_X10, rv.UC_RISCV_REG_PC
        cpu.reg_write(rv.UC_RISCV_REG_X1, STOP)
        sp, stack_bias = INITIAL_SP, 0
    cpu.mem_map(0x100000, 0x100000)
    cpu.mem_map(STACK, 0x100000)
    for address, data in functions.values(): cpu.mem_write(address, data)
    cpu.reg_write(sp_reg, sp)
    if mode < 2: cpu.mem_write(sp, STOP.to_bytes(8, 'little'))
    sentinels = {reg: 0x1234567890ABC000 + index for index, reg in enumerate(saved)}
    for reg, value in sentinels.items(): cpu.reg_write(reg, value)
    def hardware_float(kind):
        return kind.startswith('f') and (mode < 3 or mode == 5 or (mode == 4 and kind == 'f32'))
    ng, nf, ns = 0, 0, 0
    for index, (value, kind) in enumerate(zip(values, argument_kinds)):
        is_fp = hardware_float(kind)
        if kind.startswith('f'):
            bits = int.from_bytes(struct.pack('<f' if kind == 'f32' else '<d', value), 'little')
        else: bits = value & MASK
        if mode >= 3 and is_fp and kind == 'f32': bits |= 0xffffffff00000000
        registers = fprs if is_fp else gprs
        position = index if mode == 1 else nf if is_fp else ng
        if position < len(registers):
            cpu.reg_write(registers[position], bits)
            if is_fp: nf += 1
            else: ng += 1
        else:
            cpu.mem_write(sp + stack_bias + ns * 8, bits.to_bytes(8, 'little')); ns += 1
    try:
        cpu.emu_start(functions[name][0], STOP, timeout=500000, count=100000)
    except uc.UcError as error:
        raise AssertionError(f'{name}{values}: {error} at {cpu.reg_read(pc_reg):#x}') from error
    assert cpu.reg_read(pc_reg) == STOP, f'{name}: instruction/time budget exhausted'
    assert cpu.reg_read(sp_reg) == INITIAL_SP, f'{name}: stack not restored'
    for reg, value in sentinels.items():
        assert cpu.reg_read(reg) == value, f'{name}: callee-saved register {reg} corrupted'
    result = cpu.reg_read(fprs[0] if hardware_float(result_kind) else ret_reg) & MASK
    if result_kind == 'f32': return struct.unpack('<f', (result & 0xffffffff).to_bytes(4, 'little'))[0]
    if result_kind == 'f64': return struct.unpack('<d', result.to_bytes(8, 'little'))[0]
    if result_kind == 'bool': return result & 255
    return result & ((1 << int(result_kind[1:])) - 1)


def run():
    count = 0
    for mode in range(6):
        for limit in [0, 2]:
            for promote in [0, 1]:
                proc = subprocess.run([args.compiler, str(mode), str(limit), str(promote), 'core'],
                                      check=True, capture_output=True, text=True, timeout=30)
                functions = {name: (int(address), bytes.fromhex(data))
                             for name, address, data in (line.split('\t') for line in proc.stdout.splitlines())}
                cases = [('choose', [1, 17, 93], 17), ('choose', [0, 17, 93], 93),
                         ('loop_sum', [0], 0), ('loop_sum', [40], 780),
                         ('call_live', [17, 9, 31], 74), ('call9', [7, 11], 90),
                         ('sum9', list(range(1, 10)), 45), ('signed_divide', [-98, 7], -14)]
                cases += [('literal_equal', [0], 1), ('literal_equal', [1], 0),
                          ('literal_left', [42], 0), ('literal_left', [43], 1),
                          ('literal_signed', [-18], 0), ('literal_signed', [-17], 1),
                          ('literal_high', [1 << 63], 0), ('literal_high', [(1 << 63) + 1], 1),
                          ('literal_min', [-(1 << 63)], 1), ('literal_min', [0], 1),
                          ('literal_nested', [42], 0), ('literal_nested', [43], 1),
                          ('pointer_roundtrip', [0], 0), ('pointer_roundtrip', [MASK], MASK),
                          ('pointer_roundtrip', [1 << 63], 1 << 63), ('pointer_load', [41], 42)]
                rng = random.Random(771)
                for _ in range(10):
                    a, b = rng.getrandbits(64), rng.getrandbits(64) or 1
                    cases += [('add', [a, b], a + b), ('subtract', [a, b], a - b),
                              ('multiply', [a, b], a * b), ('divide', [a, b], a // b),
                              ('remainder', [a, b], a % b), ('shift_left', [a, b & 63], a << (b & 63)),
                              ('shift_right', [a, b & 63], a >> (b & 63)),
                              ('bit_mix', [a, b, 0xF0F0F0F0], (a ^ b) & 0xF0F0F0F0)]
                for name, values, expected in cases:
                    actual = execute(mode, functions, name, values)
                    assert actual == expected & MASK, f'mode={mode}, limit={limit}, promote={promote}: {name}{values}: {actual:#x} != {expected & MASK:#x}'
                    count += 1
                for name, values, expected in [('float_add', [1.25, -9.5], -8.25), ('float_const', [1.25], 3.75), ('literal_float', [1.25], 7.0), ('literal_float', [1.5], 9.0)]:
                    actual = execute(mode, functions, name, values, floating=True)
                    assert actual == expected, f'mode={mode}: {name}: {actual} != {expected}'
                    count += 1
                print(f'ABI {mode}, register limit {limit}, promotion {promote}: passed', flush=True)
                cast_proc = subprocess.run([args.compiler, str(mode), str(limit), str(promote), 'crossarch_scalar'],
                                           check=True, capture_output=True, text=True, timeout=30)
                casts = {name: (int(address), bytes.fromhex(data)) for name, address, data in
                         (line.split('\t') for line in cast_proc.stdout.splitlines())}
                cast_cases = [('signed_to_float', [-127], ['i8'], 'f32', -127.0),
                              ('widen_float', [1.25], ['f32'], 'f64', 1.25),
                              ('narrow_float', [1.25], ['f64'], 'f32', 1.25),
                              ('bits_to_float', [0xC1200000], ['u32'], 'f32', -10.0),
                              ('double_to_bits', [-10.0], ['f64'], 'u64', 0xC024000000000000),
                              ('select_integer', [0, 19, 41], ['bool', 'u64', 'u64'], 'u64', 41),
                              ('select_integer', [1, 19, 41], ['bool', 'u64', 'u64'], 'u64', 19),
                              ('select_float', [0, 1.25, -4.75], ['bool', 'f32', 'f32'], 'f32', -4.75),
                              ('select_float', [1, 1.25, -4.75], ['bool', 'f32', 'f32'], 'f32', 1.25),
                              ('float_call_live', [1.25, -4.75, 9.5], ['f32'] * 3, 'f32', 6.0)]
                for value in [0, 1, (1 << 53) - 1, (1 << 53) + 1, (1 << 63) - 1, 1 << 63, (1 << 63) + 1025, MASK]:
                    cast_cases.append(('unsigned_to_double', [value], ['u64'], 'f64', float(value)))
                for value in [0, 1, (1 << 24) + 1, (1 << 24) + 3, (1 << 63) - 1, 1 << 63,
                              (1 << 63) + (1 << 39) - 1, (1 << 63) + (1 << 39), (1 << 63) + (1 << 39) + 1, MASK]:
                    cast_cases.append(('unsigned_to_float', [value], ['u64'], 'f32', unsigned_f32(value)))
                for value in [0, 1 << 31, (1 << 32) - 1]:
                    cast_cases.append(('unsigned32_to_float', [value], ['u32'], 'f32', unsigned_f32(value)))
                    cast_cases.append(('double_to_unsigned32', [float(value)], ['f64'], 'u32', value))
                for value in [0.0, 1.75, float((1 << 63) - (1 << 39)), float(1 << 63), float((1 << 64) - (1 << 40))]:
                    cast_cases.append(('float_to_unsigned', [value], ['f32'], 'u64', int(value)))
                cast_cases += [('extend_unsigned_signed', [255], ['u8'], 'u64', MASK),
                               ('extend_signed_unsigned', [-1], ['i8'], 'u64', 255)]
                for value in [0.0, 1.75, float((1 << 63) - 2048), float(1 << 63), float((1 << 63) + 2048), float((1 << 64) - 2048)]:
                    cast_cases.append(('double_to_unsigned', [value], ['f64'], 'u64', int(value)))
                for value in [-float(1 << 63), -1234.75, 0.0, 1234.75, float((1 << 63) - 2048)]:
                    cast_cases.append(('double_to_signed', [value], ['f64'], 'u64', int(value) & MASK))
                for a, b in [(1.25, 2.5), (2.5, 1.25), (1.25, 1.25), (math.nan, 1.0), (1.0, math.nan), (math.inf, math.inf), (-0.0, 0.0)]:
                    for name, types, expected in [('float_less', ['f64'] * 2, a < b), ('float_not_equal', ['f64'] * 2, a != b),
                                                  ('float_less_equal', ['f64'] * 2, a <= b), ('float_equal', ['f32'] * 2, a == b),
                                                  ('float_greater_equal', ['f32'] * 2, a >= b)]:
                        cast_cases.append((name, [a, b], types, 'bool', expected))
                for name, values, kinds, result, expected in cast_cases:
                    actual = execute(mode, casts, name, values, argument_kinds=kinds, result_kind=result)
                    assert actual == expected, f'ABI={mode}, limit={limit}, promote={promote}: {name}{values}: {actual} != {expected}'
                    count += 1
    print(f'{count} source-to-byte CPU executions passed')


if __name__ == '__main__':
    try: run()
    except subprocess.CalledProcessError as error:
        sys.stderr.write(error.stderr)
        raise
